class Retangulo:
    def __init__(self, largura, altura):
        self.largura = largura
        self.altura = altura

    @property
    def area(self):
        return self.largura * self.altura

    def __str__(self):
        return f"Retangulo({self.largura}, {self.altura})"

    def __eq__(self, outro):
        return isinstance(outro, Retangulo) and self.largura == outro.largura and self.altura == outro.altura

print(Retangulo(2, 3).area)
print(Retangulo(2, 3))

